import{_ as e}from"./chunks/led-battery-levels.BJDA0Ncv.js";import{af as a,z as r,J as o,ab as i}from"./chunks/framework.C1QHhBQn.js";const f=JSON.parse('{"title":"Zero3 (ZE3) LED indicators","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"guides/ze3-leds.md","filePath":"guides/ze3-leds.md"}'),s={name:"guides/ze3-leds.md"};function n(d,t,l,h,c,p){return r(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...t[0]||(t[0]=[i('<h1 id="zero3-ze3-led-indicators" tabindex="-1">Zero3 (ZE3) LED indicators <a class="header-anchor" href="#zero3-ze3-led-indicators" aria-label="Permalink to &quot;Zero3 (ZE3) LED indicators&quot;">​</a></h1><p>This page covers the <strong>ZE3 revision 01 design and standard firmware display</strong>. It is not the <a href="/docs/pr/40/guides/tracker-leds#zero-ze2">ZeroN/ZE2 guide</a>, and does not establish which firmware is installed on a supplied ZE3. Check the revision with support if it is not known.</p><p>ZE3 revision 01 has four orange indicators and no separate GPS/mobile-network diagnostic pair. Use these four lights for the battery and charging patterns below, not the older six-indicator colour table.</p><h2 id="normal-battery-display" tabindex="-1">Normal battery display <a class="header-anchor" href="#normal-battery-display" aria-label="Permalink to &quot;Normal battery display&quot;">​</a></h2><p>A short status-button press normally shows the battery level briefly. The four indicators use these approximate bands:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Normal battery display</th></tr></thead><tbody><tr><td>Below 20%</td><td>First indicator flashes when showing status off charge</td></tr><tr><td>20% to below 40%</td><td>1 indicator</td></tr><tr><td>40% to below 60%</td><td>2 indicators</td></tr><tr><td>60% to below 80%</td><td>3 indicators</td></tr><tr><td>80% or more</td><td>4 indicators</td></tr></tbody></table><p>These bands apply to the normal battery display only. Startup, alerts and application-controlled patterns can use the same lights for a different reason. Four lights are not an exact 100% reading.</p><figure><img src="'+e+'" alt="Four orange battery indicators: below 20 percent the first flashes off charge; at least 20, 40, 60 and 80 percent shows one, two, three and four indicators." tabindex="0"><figcaption>Four orange battery indicators: below 20 percent the first flashes off charge; at least 20, 40, 60 and 80 percent shows one, two, three and four indicators.</figcaption></figure><h2 id="charging" tabindex="-1">Charging <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;Charging&quot;">​</a></h2><ul><li>Below about 95%, the highest lit battery indicator blinks, roughly one second on and one second off. At very low charge, the first indicator blinks.</li><li>At about 95% or above, the normal charging display becomes steady. This means a high charge level, not an exact 100% reading.</li><li>When unplugged and resting, the lights normally go out after any temporary status display finishes. A button press, startup or other activity can still light them.</li></ul><p>These are the standard battery-bar patterns. They are not the RGB charging colours used by RH2.</p><h2 id="startup-and-other-patterns" tabindex="-1">Startup and other patterns <a class="header-anchor" href="#startup-and-other-patterns" aria-label="Permalink to &quot;Startup and other patterns&quot;">​</a></h2><p>Startup and alerts can light or sequence the same indicators. Let startup finish, then check the latest successful communication in the app or portal. Do not infer a GPS fix or a successful upload from four lit indicators.</p><p>Custom applications and remote LED control can change these patterns. For an unfamiliar or persistent display, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact support</a> with the device ID, revision and a short video. Choose another model in the <a href="/docs/pr/40/guides/leds">LED guide</a>.</p>',14)])])}const b=a(s,[["render",n]]);export{f as __pageData,b as default};
